// TeamSpeak 3 Server Query library
//
// Reference: http://goo.gl/OpJXz
package ts3

import (
	"bufio"
	"fmt"
	"io"
	stdlog "log"
	"net"
	"os"
	"strings"
	"time"
)

const (
	DefaultPort    = "10011"
	VerificationID = "TS3"
)

// Custom logger
var log = stdlog.New(os.Stdout, "ts3> ", stdlog.LstdFlags)

var (
	ReadAfter    = 100 * time.Millisecond
	DialTimeout  = 1 * time.Second
	ReadTimeout  = 2 * time.Second
	WriteTimeout = 1500 * time.Millisecond
)

type Conn struct {
	addr string
	conn net.Conn
	// In holds messages written to server
	// Out holds messages read from server
	In, Out chan string
	quit    chan bool
	r       *bufio.Reader
	w       *bufio.Writer
}

// Dial connects to a local/remote TS3 server. A default port is appended to
// `addr` if user doesn't provide one.
func Dial(addr string) *Conn {
	var (
		err  error
		line string
	)

	// Append DefaultPort if user didn't specify one
	if !strings.Contains(addr, ":") {
		addr += ":" + DefaultPort
	}

	// Try to establish connection
	c, err := net.DialTimeout("tcp", addr, DialTimeout)
	fatal(err, fmt.Sprintf("Connection error: %v\n", err))

	// Allocate connection object
	ts3conn := &Conn{
		addr: addr,
		conn: c,
		In:   make(chan string),
		Out:  make(chan string),
		quit: make(chan bool),
		r:    bufio.NewReader(c),
		w:    bufio.NewWriter(c),
	}

	// Buffer to read from TCP socket; Read first line
	line, err = ts3conn.r.ReadString('\n')
	fatal(err, "Couldn't identify server.")
	fmt.Print(line)

	// Then check if it's a TS3 server
	if !strings.Contains(line, VerificationID) {
		log.Fatal("Not a TeamSpeak 3 server.")
	}

	// Show welcome message
	line, err = ts3conn.r.ReadString('\n')
	fatal(err, "Couldn't recv welcome message.")
	fmt.Print(line)

	// Copy flow: writer (request) -> conn -> reader (response)
	go cp(ts3conn.w, c)
	go cp(c, ts3conn.r)

	// Workers parse
	go ts3conn.inWorker()
	go ts3conn.outWorker()

	return ts3conn
}

// cp copies from an io.Reader to an io.Writer
func cp(dst io.Writer, src io.Reader) {
	_, err := io.Copy(dst, src)
	fatal(err)
}

// Close closes underlying TCP Conn to local/remote server.
func (c *Conn) Close() error {
	// Two workers need two quit signals
	c.quit <- true
	c.quit <- true

	return c.conn.Close()
}

// Cmd sends an arbitrary command to the server and expects an output.
func (c *Conn) Cmd(s string) {
	fmt.Println("> " + s)
	c.In <- s
	fmt.Println(<-c.Out)
}

// inWorker writes (copies) incoming requests to its underlying io.Writer.
func (c *Conn) inWorker() {
	var err error

	for {
		select {
		case line := <-c.In:
			c.conn.SetWriteDeadline(time.Now().Add(WriteTimeout))

			_, err = c.w.WriteString(line)
			fatal(err)

			err = c.w.Flush()
			fatal(err)
		case <-c.quit:
			return
		}
	}
}

// inWorker reads (copies) incoming responses to its underlying io.Reader.
func (c *Conn) outWorker() {
	for {
		select {
		// Check if there's something to receive
		case <-time.After(ReadAfter):
			var (
				end   bool
				chunk string
			)

			// Read until end of response (error footer)
			for !end {
				line, err := c.r.ReadString('\n')
				fatal(err)

				// Trim network control chars
				line = StringsTrimNet(line)
				chunk += line

				// Determine end of line
				if strings.HasPrefix(line, "error id=") ||
					strings.Contains(line, "notify") {
					c.Out <- chunk
					// EOL found, finish iteration
					end = true
				}
			}
		case <-c.quit:
			return
		}
	}
}

// fatal exits application if encounters an error
func fatal(err error, s ...string) {
	if err != nil {
		if len(s) == 0 {
			log.Fatal(err)
		} else {
			log.Fatal(s)
		}
	}
}

package main

import (
	"bufio"
	"fmt"
	"log"
	"net"
	"os"
	"strings"
	"time"

	"github.com/toqueteos/ts3"
)

func main() {
	in := make(chan string)
	q := make(chan bool)

	// Connect to Server Query daemon
	c, err := net.DialTimeout("tcp", "127.0.0.1:10011", time.Second)
	if err != nil {
		log.Println(err)
	}
	defer c.Close()

	buf := bufio.NewReader(c)
	go stdin(in, q)

	go func(c net.Conn, in chan string, q chan bool) {
		for {
			select {
			case line := <-in:
				c.SetWriteDeadline(time.Now().Add(500 * time.Millisecond))
				c.Write([]byte(line))
			case <-q:
				return
			}
		}
	}(c, in, q)

	for {
		c.SetReadDeadline(time.Now().Add(500 * time.Millisecond))

		s, err := buf.ReadString('\n')
		if err != nil {
			log.Fatal(err)
		}

		if len(s) > 1 {
			fmt.Print(s)
		}
	}

}

func stdin(chIn chan string, q chan bool) {
	// Feed ts3.In
	in := bufio.NewReader(os.Stdin)

	for {
		// repl thingy
		line, err := in.ReadString('\n')
		if err != nil {
			fmt.Printf("ts3> stdin read error: %v\n", err)
		}
		line = ts3.StringsTrimNet(line)

		// Ignore empty lines
		if line != "\n" {
			chIn <- line

			if strings.HasPrefix(line, "quit") {
				q <- true
				break
			}
		}
	}
}

package ts3

import (
	"bufio"
	"bytes"
	"errors"
	"io"
	"net"
	"strings"
	"sync"
	"time"
)

const (
	DefaultPort    = "10011"
	VerificationID = "TS3"
)

var (
	// ts3.Dial max timeout
	DialTimeout    = 1 * time.Second
	CommandTimeout = 350 * time.Millisecond
)

type notification func(string, string)

type Conn struct {
	conn          net.Conn
	rbuf          *bufio.Reader
	wbuf          *bufio.Writer
	cResult       chan string
	cNotification chan string
	cError        chan ErrorMsg
	notifyCb      notification
	cmdSync       *sync.WaitGroup
	cmdLast       time.Time
	cmdTimeout    time.Duration
}

type ErrorMsg struct {
	Id  int
	Msg string
}

// Dial connects to a local/remote TS3 server. A default port is appended to
// `addr` if user doesn't provide one.
func Dial(addr string, whitelisted bool) (*Conn, error) {
	var (
		err  error
		line string
	)

	// Append DefaultPort if user didn't specify one
	if !strings.Contains(addr, ":") {
		addr += ":" + DefaultPort
	}

	// Try to establish connection
	conn, err := net.DialTimeout("tcp", addr, DialTimeout)
	if err != nil {
		return nil, err
	}

	// Create buffers
	rbuf := bufio.NewReader(conn)
	wbuf := bufio.NewWriter(conn)

	timeout := time.Duration(350 * time.Millisecond)
	if whitelisted {
		timeout = time.Duration(0 * time.Millisecond)
	}

	// Allocate connection object
	ts3conn := &Conn{
		conn:          conn,
		rbuf:          rbuf,
		wbuf:          wbuf,
		cResult:       make(chan string),
		cNotification: make(chan string),
		cError:        make(chan ErrorMsg),
		notifyCb:      nil,
		cmdSync:       new(sync.WaitGroup),
		cmdLast:       time.Now(),
		cmdTimeout:    timeout,
	}

	// Read VerificationID
	line, err = rbuf.ReadString('\n')

	// Then check if it's a TS3 server
	if !strings.Contains(line, VerificationID) {
		return nil, errors.New("Invalid VerificationID")
	}

	// Read welcome message
	line, err = rbuf.ReadString('\n')

	// Sync socket incoming data, to ts3conn
	go ts3conn.sync()

	return ts3conn, nil
}

// Close closes underlying TCP Conn to local/remote server.
func (this *Conn) Close() error {
	return this.conn.Close()
}

// Cmd sends a request to a server and waits for its response.
func (this *Conn) Cmd(cmd string) (string, ErrorMsg) {
	//Make sure only 1 command runs at a time per connection
	this.cmdSync.Wait()
	this.cmdSync.Add(1)

	//Make sure we timeout nicely per command to avoid spamming
	diff := time.Since(this.cmdLast)
	if diff < this.cmdTimeout {
		<-time.After(this.cmdTimeout - diff)
	}

	var (
		result string   //Holds end result
		temp   string   //Holds temp result
		err    ErrorMsg //Holds error message
	)

	// Write the cmd to the socket, ending with a \n
	this.send(cmd + "\n")

	// Block on a channel that will recieve the socket READ that is NOT a notification or error
	// Block on a channel that will recieve the socket READ that is NOT a notification or result
	done := false
	for !done {
		select {
		case temp = <-this.cResult:
			result += temp
			continue
		case err = <-this.cError:
			done = true
		case <-time.After(CommandTimeout):
			//TODO Is there a better way to handle this?
			err.Id = 1
			err.Msg = "timeout"
			done = true
		}
	}

	this.cmdLast = time.Now()
	this.cmdSync.Done()
	return result, err
}

func (this *Conn) NotifyFunc(cb notification) {
	this.notifyCb = cb
}

func (this *Conn) send(p string) (int, error) {
	b := []byte(p)
	// Double IAC chars
	bytes.Replace(b, []byte{0xff}, []byte{0xff, 0xff}, -1)
	return this.conn.Write(b)
}

func (this *Conn) handleResponse(data string) {
	// Has to be done by line!
	// Sadly its possible, when spammed, to have an error and notification to stick together, and more
	// Should be a better way to solve this overall, but teamspeak is a bitch and doesnt have a standard way to end a reply

	lines := strings.Split(data, "\n")
	var result string

	for _, line := range lines {
		switch {
		case strings.HasPrefix(line, "error"):
			this.cError <- parseError(line)
		case strings.HasPrefix(line, "notify"):
			if this.notifyCb != nil {
				split := strings.SplitN(line, " ", 2)
				go this.notifyCb(split[0], split[1])
			}
		default:
			result += line
		}
	}

	if result != "" {
		this.cResult <- result
	}
}

// Write writes the contents of p into the buffer. It returns the number of bytes written.
func (this *Conn) Write(p []byte) (int, error) {
	s := string(p)
	s = strings.Replace(s, "\r", "", -1)

	this.handleResponse(s)
	return len(s), nil
}

// cp copies from an io.Reader to an io.Writer
func (this *Conn) sync() {
	for {
		io.Copy(this, this.conn)
	}
}

